#!/usr/bin/env python3"""Collection Statistics GeneratorAnalyzes the entire music collection and generates comprehensive statistics."""import osimport sysimport jsonfrom pathlib import Pathfrom collections import defaultdict, Counterfrom datetime import datetime# ConfigurationAUDIO_ROOT = "/Volumes/Eksternal/Audio"GENRES = ["Metal", "Punk & Hardcore", "Electronic", "Hip-Hop", "Rock & Grunge", "Miscellaneous"]class CollectionStats:    def __init__(self, root_path):        self.root = Path(root_path)        self.stats = {            'generated_at': datetime.now().isoformat(),            'genres': {},            'totals': {                'artists': 0,                'albums': 0,                'tracks': 0,                'size_bytes': 0,                'size_gb': 0.0            },            'formats': Counter(),            'decades': Counter(),            'artwork_coverage': {                'albums_with_covers': 0,                'albums_without_covers': 0,                'artists_with_logos': 0,                'artists_without_logos': 0            },            'documentation': {                'albums_with_info': 0,                'albums_with_markdown': 0,                'artists_with_docs': 0            },            'special_collections': {                'compilations': 0,                'splits': 0,                'singles': 0            }        }        def is_audio_file(self, filename):        """Check if file is an audio file."""        audio_extensions = {'.mp3', '.flac', '.m4a', '.wav', '.ogg', '.wma', '.aac', '.opus'}        return Path(filename).suffix.lower() in audio_extensions        def is_album_folder(self, path):        """Check if folder matches album naming pattern (YYYY - Title)."""        name = path.name        if len(name) < 7:            return False        # Check for YYYY - Title pattern        if name[4:7] == ' - ' and name[:4].isdigit():            return True        return False        def get_decade(self, album_folder_name):        """Extract decade from album folder name."""        try:            year = int(album_folder_name[:4])            return (year // 10) * 10        except (ValueError, IndexError):            return None        def scan_album(self, album_path):        """Scan an album folder and return stats."""        album_stats = {            'tracks': 0,            'size': 0,            'formats': Counter(),            'has_cover': False,            'has_info_txt': False,            'has_album_info_md': False        }                try:            for item in album_path.iterdir():                if item.is_file():                    # Count audio tracks                    if self.is_audio_file(item.name):                        album_stats['tracks'] += 1                        album_stats['formats'][item.suffix.lower()] += 1                        album_stats['size'] += item.stat().st_size                                        # Check for documentation                    elif item.name.lower() == 'cover.jpg' or item.name.lower() == 'cover.png':                        album_stats['has_cover'] = True                    elif item.name.lower() == 'info.txt':                        album_stats['has_info_txt'] = True                    elif item.name.lower() == 'album_info.md':                        album_stats['has_album_info_md'] = True                                # Handle multi-disc albums                elif item.is_dir() and item.name.startswith('Disc '):                    disc_stats = self.scan_album(item)                    album_stats['tracks'] += disc_stats['tracks']                    album_stats['size'] += disc_stats['size']                    album_stats['formats'].update(disc_stats['formats'])                except PermissionError:            pass                return album_stats        def scan_artist(self, artist_path):        """Scan an artist folder and return stats."""        artist_stats = {            'albums': 0,            'tracks': 0,            'size': 0,            'formats': Counter(),            'decades': Counter(),            'has_logo': False,            'has_docs': False        }                try:            for item in artist_path.iterdir():                if item.is_dir() and self.is_album_folder(item):                    # Scan album                    album_stats = self.scan_album(item)                    artist_stats['albums'] += 1                    artist_stats['tracks'] += album_stats['tracks']                    artist_stats['size'] += album_stats['size']                    artist_stats['formats'].update(album_stats['formats'])                                        # Track decade                    decade = self.get_decade(item.name)                    if decade:                        artist_stats['decades'][decade] += 1                        self.stats['decades'][decade] += 1                                        # Track artwork coverage                    if album_stats['has_cover']:                        self.stats['artwork_coverage']['albums_with_covers'] += 1                    else:                        self.stats['artwork_coverage']['albums_without_covers'] += 1                                        # Track documentation                    if album_stats['has_info_txt']:                        self.stats['documentation']['albums_with_info'] += 1                    if album_stats['has_album_info_md']:                        self.stats['documentation']['albums_with_markdown'] += 1                                elif item.is_file():                    # Check for artist logo                    if 'logo' in item.name.lower() and item.suffix.lower() in {'.png', '.jpg', '.jpeg'}:                        artist_stats['has_logo'] = True                    # Check for artist docs                    elif item.suffix.lower() in {'.md', '.pdf'} and item.name != 'album_info.md':                        artist_stats['has_docs'] = True                except PermissionError:            pass                return artist_stats        def scan_letter_folder(self, letter_path):        """Scan a letter folder (A-Z, #) and return stats."""        letter_stats = {            'artists': 0,            'albums': 0,            'tracks': 0,            'size': 0,            'formats': Counter()        }                try:            for item in letter_path.iterdir():                if item.is_dir():                    artist_stats = self.scan_artist(item)                    letter_stats['artists'] += 1                    letter_stats['albums'] += artist_stats['albums']                    letter_stats['tracks'] += artist_stats['tracks']                    letter_stats['size'] += artist_stats['size']                    letter_stats['formats'].update(artist_stats['formats'])                                        # Track logo coverage                    if artist_stats['has_logo']:                        self.stats['artwork_coverage']['artists_with_logos'] += 1                    else:                        self.stats['artwork_coverage']['artists_without_logos'] += 1                                        # Track artist documentation                    if artist_stats['has_docs']:                        self.stats['documentation']['artists_with_docs'] += 1                except PermissionError:            pass                return letter_stats        def scan_genre(self, genre_name):        """Scan a genre folder and return stats."""        genre_path = self.root / genre_name        genre_stats = {            'artists': 0,            'albums': 0,            'tracks': 0,            'size_bytes': 0,            'size_gb': 0.0,            'formats': {},            'decades': {}        }                if not genre_path.exists():            return genre_stats                print(f"Scanning {genre_name}...")                try:            for item in genre_path.iterdir():                if item.is_dir():                    item_name = item.name                                        # Special folders                    if item_name == '-Compilations-':                        comp_stats = self.scan_letter_folder(item)                        self.stats['special_collections']['compilations'] += comp_stats['albums']                        genre_stats['albums'] += comp_stats['albums']                        genre_stats['tracks'] += comp_stats['tracks']                        genre_stats['size_bytes'] += comp_stats['size']                                        elif item_name == '-Splits-':                        split_stats = self.scan_letter_folder(item)                        self.stats['special_collections']['splits'] += split_stats['albums']                        genre_stats['albums'] += split_stats['albums']                        genre_stats['tracks'] += split_stats['tracks']                        genre_stats['size_bytes'] += split_stats['size']                                        elif item_name == '-Singles-':                        single_stats = self.scan_letter_folder(item)                        self.stats['special_collections']['singles'] += single_stats['albums']                        genre_stats['albums'] += single_stats['albums']                        genre_stats['tracks'] += single_stats['tracks']                        genre_stats['size_bytes'] += single_stats['size']                                        # Regular letter folders (A-Z, #)                    elif len(item_name) <= 2 and (item_name.isalpha() or item_name == '#'):                        letter_stats = self.scan_letter_folder(item)                        genre_stats['artists'] += letter_stats['artists']                        genre_stats['albums'] += letter_stats['albums']                        genre_stats['tracks'] += letter_stats['tracks']                        genre_stats['size_bytes'] += letter_stats['size']                                                # Aggregate formats                        for fmt, count in letter_stats['formats'].items():                            self.stats['formats'][fmt] += count                except PermissionError:            pass                genre_stats['size_gb'] = round(genre_stats['size_bytes'] / (1024**3), 2)        return genre_stats        def generate(self):        """Generate comprehensive collection statistics."""        print("=== Collection Statistics Generator ===\n")                # Scan each genre        for genre in GENRES:            self.stats['genres'][genre] = self.scan_genre(genre)                # Calculate totals        for genre_stats in self.stats['genres'].values():            self.stats['totals']['artists'] += genre_stats['artists']            self.stats['totals']['albums'] += genre_stats['albums']            self.stats['totals']['tracks'] += genre_stats['tracks']            self.stats['totals']['size_bytes'] += genre_stats['size_bytes']                self.stats['totals']['size_gb'] = round(            self.stats['totals']['size_bytes'] / (1024**3), 2        )                # Convert decades Counter to sorted dict        self.stats['decades'] = dict(sorted(self.stats['decades'].items()))                # Convert formats Counter to dict        self.stats['formats'] = dict(self.stats['formats'])                return self.stats        def save_json(self, output_path):        """Save stats as JSON."""        with open(output_path, 'w') as f:            json.dump(self.stats, f, indent=2)        print(f"\n✓ JSON saved to: {output_path}")        def generate_markdown(self, output_path):        """Generate markdown report."""        s = self.stats                md = f"""# Collection Statistics*Generated: {datetime.now().strftime('%B %d, %Y at %I:%M %p')}*## Overview{s['totals']['tracks']:,} tracks across {s['totals']['albums']:,} albums from {s['totals']['artists']:,} artists, organized into {len(GENRES)} major genres.**Total Storage**: {s['totals']['size_gb']:,.2f} GB## By Genre| Genre | Artists | Albums | Tracks | Storage ||-------|---------|--------|--------|---------|"""                # Sort genres by size        sorted_genres = sorted(            s['genres'].items(),            key=lambda x: x[1]['size_gb'],            reverse=True        )                for genre, stats in sorted_genres:            md += f"| {genre} | {stats['artists']:,} | {stats['albums']:,} | {stats['tracks']:,} | {stats['size_gb']:.2f} GB |\n"                md += f"\n**Total** | {s['totals']['artists']:,} | {s['totals']['albums']:,} | {s['totals']['tracks']:,} | {s['totals']['size_gb']:.2f} GB\n"                # Format distribution        if s['formats']:            md += "\n## Audio Formats\n\n"            total_tracks = sum(s['formats'].values())            sorted_formats = sorted(s['formats'].items(), key=lambda x: x[1], reverse=True)                        for fmt, count in sorted_formats:                pct = (count / total_tracks) * 100                md += f"- **{fmt}**: {count:,} tracks ({pct:.1f}%)\n"                # Decade distribution        if s['decades']:            md += "\n## Albums by Decade\n\n"            for decade, count in sorted(s['decades'].items()):                md += f"- **{decade}s**: {count:,} albums\n"                # Artwork coverage        ac = s['artwork_coverage']        total_albums = ac['albums_with_covers'] + ac['albums_without_covers']        total_artists = ac['artists_with_logos'] + ac['artists_without_logos']                if total_albums > 0:            cover_pct = (ac['albums_with_covers'] / total_albums) * 100            md += f"\n## Artwork Coverage\n\n"            md += f"- **Album Covers**: {ac['albums_with_covers']:,} / {total_albums:,} albums ({cover_pct:.1f}%)\n"                if total_artists > 0:            logo_pct = (ac['artists_with_logos'] / total_artists) * 100            md += f"- **Artist Logos**: {ac['artists_with_logos']:,} / {total_artists:,} artists ({logo_pct:.1f}%)\n"                # Documentation coverage        doc = s['documentation']        if total_albums > 0:            info_pct = (doc['albums_with_info'] / total_albums) * 100            md_pct = (doc['albums_with_markdown'] / total_albums) * 100                        md += f"\n## Documentation\n\n"            md += f"- **info.txt files**: {doc['albums_with_info']:,} albums ({info_pct:.1f}%)\n"            md += f"- **album_info.md files**: {doc['albums_with_markdown']:,} albums ({md_pct:.1f}%)\n"            md += f"- **Artist documentation**: {doc['artists_with_docs']:,} artists\n"                # Special collections        sc = s['special_collections']        if any(sc.values()):            md += f"\n## Special Collections\n\n"            if sc['compilations'] > 0:                md += f"- **Compilations**: {sc['compilations']:,} albums\n"            if sc['splits'] > 0:                md += f"- **Split Releases**: {sc['splits']:,} albums\n"            if sc['singles'] > 0:                md += f"- **Singles**: {sc['singles']:,} releases\n"                md += "\n---\n\n*Statistics generated by collection_stats.py*\n"                with open(output_path, 'w') as f:            f.write(md)                print(f"✓ Markdown saved to: {output_path}")if __name__ == "__main__":    import sys        # Allow override of audio root path    if len(sys.argv) > 1:        audio_root = sys.argv[1]    else:        audio_root = AUDIO_ROOT        # Check if path exists    if not Path(audio_root).exists():        print(f"ERROR: Path not found: {audio_root}")        print(f"\nUsage: python3 collection_stats.py [/path/to/Audio]")        print(f"\nDefault path: {AUDIO_ROOT}")        sys.exit(1)        stats = CollectionStats(audio_root)    results = stats.generate()        # Save outputs to same directory as audio root    output_dir = Path(audio_root)    stats.save_json(str(output_dir / 'stats.json'))    stats.generate_markdown(str(output_dir / 'STATS.md'))        print("\n✨ Statistics generation complete!")